 css='''<style id="MM_WOODNEUCE_CSS">.mm-wood-grid{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.mm-wood-btn{display:flex;align-items:center;gap:9px;text-align:left;border:1px solid #d5dbe0;background:#fff;border-radius:11px;padding:9px 10px;cursor:pointer}.mm-wood-btn.active{border:2px solid #f28c00;box-shadow:0 0 0 3px rgba(242,140,0,.12)}.mm-wood-dot{width:30px;height:30px;border-radius:50%;border:1px solid #c5cbd0;flex:none}.mm-wood-btn b,.mm-wood-btn small{display:block}.mm-wood-btn small{color:#69747e;font-size:10px}</style>'''
 js='''<script id="MM_WOODNEUCE_FINAL_JS">(function(){if((new URLSearchParams(location.search).get('slug')||'').toLowerCase()!=='woodneuce')return;let i=0;function go(){if(!window.P||!document.querySelector('.variant-grid'))return false;let g=document.querySelector('.variant-grid'),t=document.querySelector('.variant-title'),v=P.variants||[];if(!v.length)return false;t.textContent='Escolha o acabamento e a cor';g.className='mm-wood-grid';g.innerHTML=v.map((x,k)=>`<button type="button" class="mm-wood-btn ${k===i?'active':''}" data-i="${k}"><span class="mm-wood-dot" style="background:${esc(x.color_hex||'#ddd')}"></span><span><b>${esc(x.finish)}</b><small>${esc(x.color_code)} — ${esc(x.color)}</small></span></button>`).join('');g.querySelectorAll('button').forEach(b=>b.onclick=()=>{i=+b.dataset.i;variant=v[i];document.getElementById('priceBox').innerHTML='<div class="price">'+money(variant.price)+'</div>';g.querySelectorAll('button').forEach((z,k)=>z.classList.toggle('active',k===i))});return true}let n=0,q=setInterval(()=>{if(go()||++n>80)clearInterval(q)},100)})();</script>'''
