 js='''<script id="MM_PAINT_FIELDS_20260910">(function(){function add(){if(document.getElementById('mmPaintTest'))return;let h=document.querySelector('.content')||document.querySelector('.main');if(!h)return;let e=document.createElement('section');e.id='mmPaintTest';e.className='panel mm-paint-test';e.innerHTML=`<h3>🎨 Campos especiais — Pinturas</h3><p>Testar e editar os campos usados nas pinturas.</p><div class="mmf"><label>Slug<input id="mmps" placeholder="woodneuce"></label><label>Subfamília<select id="mmpsub"><option>Primários - Interiores</option><option>Primários - Exteriores</option><option>Tintas - Interiores</option><option>Tintas - Exteriores</option><option>Esmaltes - Ferro</option><option>Esmaltes - Madeira</option><option>Esmaltes - Industriais</option><option>Lasures</option></select></label><label>Acabamento<select id="mmf"><option>Mate</option><option>Brilhante</option></select></label><label>Cor<input id="mmc" placeholder="215 — Pinho Oregon"></label><label>Embalagem<input id="mmp" placeholder="5L"></label><label>Preço<input id="mmpr" placeholder="24,90 €"></label><label>Imagem principal<input id="mmi"></label></div><button class="btn" id="mms" style="margin-top:12px">Guardar no produto</button><span id="mmm" style="margin-left:10px"></span>`;h.appendChild(e);document.getElementById('mms').onclick=async()=>{let slug=document.getElementById('mmps').value.trim();if(!slug)return;let body={slug,family:'Pinturas',category:'Pinturas',subfamily:document.getElementById('mmpsub').value,image:document.getElementById('mmi').value,variants:[{name:document.getElementById('mmp').value||'5L',finish:document.getElementById('mmf').value,color:document.getElementById('mmc').value,price:document.getElementById('mmpr').value,stock:'Disponível'}]};let r=await fetch('/api/admin/product',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});document.getElementById('mmm').textContent=r.ok?'✓ Guardado':'Erro ao guardar'};}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',add);else add()})();</script>'''
